\label{theorem:CBF_safety}
Suppose $b(x)$ is a CBF with $b(x(0))\geq 0$ and the input $u(t)$ satisfies
\begin{equation}\label{eq:cbf_ode}
\mathcal{L}_{f} b(x) + \mathcal{L}_{g} b(x)\,u \geq -\alpha\big(b(x)\big),
\end{equation}
for all $t\geq 0$, where $f:=f_d$ and $g:=g_d$. Then $\mathcal{D}$ is positively invariant.

\label{thm:positive_invariance}
Consider the semi-explicit DAE~\eqref{eq:dyn} with $\nu=1$ satisfying Assumption~\ref{assumption:regularity}. Suppose $b(x(0))\geq 0$ and $x(0)\in\mathcal{D}\cap\mathcal{M}$. The set $\mathcal{D}\cap\mathcal{M}$ is positively invariant if the input $u(t)$ satisfies, for all $x\in\mathcal{D}\cap\mathcal{M}$,
\begin{subequations}\label{eq:invariance_conditions}
\begin{align}
P(x)\big(J_d(x)f_d(x) + J_d(x)g_d(x)u\big) &= 0, \label{eq:compat_cond}\\
\mathcal{L}_{\hat{f}}b(x) + \mathcal{L}_{\hat{g}}b(x)u &\geq -\alpha(b(x)). \label{eq:cbf_cond}
\end{align}
\end{subequations}

\label{cor:autonomous_index1}
Consider the DAE system~\eqref{eq:dyn} satisfying Assumption~\ref{assumption:regularity}, with $g_d(x)\equiv 0$ (no control input). Suppose $b(x(0))\geq 0$ and $x(0)\in\mathcal{D}\cap\mathcal{M}$. Then $\mathcal{D}\cap\mathcal{M}$ is positively invariant if, for all $x\in\mathcal{D}\cap\mathcal{M}$,
\begin{subequations}\label{eq:autonomous_invariance_conditions}
\begin{align}
P(x)J_d(x)f_d(x) &= 0, \label{eq:autonomous_compat}\\
\mathcal{L}_{\hat{f}}b(x) &\geq -\alpha(b(x)). \label{eq:autonomous_cbf}
\end{align}
\end{subequations}

\label{cor:hocbf}
Consider a semi-explicit DAE system satisfying Assumption~\ref{assumption:regularity}. Let $b(x)$ have relative degree $d\geq 1$ on $\mathcal{M}$ with respect to~\eqref{eq:projected_fields}. Define the HOCBF hierarchy $\psi_0(x):=b(x)$ and
\begin{equation}\label{eq:hocbf_hierarchy}
\psi_i(x) := \mathcal{L}_{\hat{f}}\psi_{i-1}(x) + \alpha_i(\psi_{i-1}(x)), \quad i=1,\ldots,d,
\end{equation}
for class-$\mathcal{K}_\infty$ functions $\alpha_i$. Then $\mathcal{D}\cap\mathcal{M}$ is positively invariant if there exists $u$ such that
\begin{subequations}\label{eq:hocbf_conditions}
\begin{align}
P(x)\big(J_d(x)f_d(x) + J_d(x)g_d(x)u\big) &= 0, \label{eq:hocbf_compat}\\
\mathcal{L}_{\hat{f}}\psi_{d-1}(x) + \alpha_d(\psi_{d-1}(x)) + \mathcal{L}_{\hat{g}}\psi_{d-1}(x)u &\geq 0, \label{eq:hocbf_cbf}
\end{align}
\end{subequations}
hold for all $x\in\mathcal{D}\cap\mathcal{M}$ with $\psi_i(x(0))\geq 0$ for $i=0,\ldots,d$.

\label{lem:correctness}
Assume $h$, $b$, and $\phi$ are polynomials and $\mathcal{D}\cap\mathcal{M}$ is compact. Then $\mathcal{D}\cap\mathcal{M}\subseteq\mathcal{C}\cap\mathcal{M}$ if there exist SOS polynomials $\sigma_0,\sigma_1,\sigma_2$, polynomial multipliers $\rho_\ell$ for $\ell=1,\ldots,n_m$, and integer $k\geq 1$ such that
\begin{equation}\label{eq:correctness_identity}
\hspace{-0.2cm}\sigma_0 \hspace{-0.05cm}+ \hspace{-0.05cm}\sigma_1 b(x) \hspace{-0.05cm}+\hspace{-0.05cm} \sigma_2(-h(x)-s^2) \hspace{-0.05cm}+ \hspace{-0.05cm}s^{2k} \hspace{-0.05cm}+ \hspace{-0.05cm}\sum_{\ell=1}^{n_m} \rho_\ell\phi_\ell(x) \hspace{-0.05cm}= \hspace{-0.05cm}0.
\end{equation}

\label{thm:verification}
Let $b$ define the barrier set $\mathcal{D}:=\{x:b(x)\geq 0\}$. Then $b$ is a valid DAE-aware CBF (Definition~\ref{def:valid_dae_cbf}) if and only if
\begin{enumerate}
\item (Correctness) $\mathcal{D}\cap\mathcal{M}\subseteq\mathcal{C}\cap\mathcal{M}$;
\item (Interior feasibility) For every $x\in\mathrm{int}(\mathcal{D})\cap\mathcal{M}$, the dual system $\lambda^\top A_{\mathrm{int}}(x)=0^\top$, $\lambda^\top r_{\mathrm{int}}(x)<0$ admits no $\lambda\geq 0$;
\item (Boundary tangency) For every $x\in\partial\mathcal{D}\cap\mathcal{M}$, the dual system $\lambda^\top \hspace{-0.05cm}A_{\mathrm{bnd}}(x)\hspace{-0.05cm}=\hspace{-0.05cm}0^\top$, \hspace{-0.05cm} $\lambda^\top \hspace{-0.05cm}r_{\mathrm{bnd}}(x)\hspace{-0.05cm}<\hspace{-0.05cm}0$ admits no $\hspace{-0.05cm}\lambda\geq \hspace{-0.05cm}0$.
\end{enumerate}

\label{prop:sos_certificates}
Let $f_d$, $g_d$, $J_d$, $P$, and $b$ be polynomial, let $\mathcal{M}$ and $\mathcal{C}$ admit polynomial equality and inequality expressions, and let $\mathcal{D}\cap\mathcal{M}$ be compact. Then conditions~2 and~3 of Theorem~\ref{thm:verification} hold if there exist SOS polynomials and multipliers that satisfy
\begin{align}
\Phi_{\mathrm{int}}(x,\lambda_{\mathrm{int}}) + s_{\mathrm{int}}^{2} + \varphi_{\mathrm{int}}(x,\lambda_{\mathrm{int}}) &= 0, \label{eq:sos_int}\\
\Phi_{\mathrm{bnd}}(x,\lambda_{\mathrm{bnd}}) + s_{\mathrm{bnd}}^{2} + \varphi_{\mathrm{bnd}}(x,\lambda_{\mathrm{bnd}}) &= 0, \label{eq:sos_bnd}
\end{align}
where $\Phi_{\mathrm{int}}\!\in\!\Sigma_{\mathrm{int}}$ denotes the cone generated by $b(x)\!\geq\! 0$, $\lambda_{\mathrm{int}}\!\geq\! 0$;
$\Phi_{\mathrm{bnd}}\!\in\!\Sigma_{\mathrm{bnd}}$ denotes the cone generated by $\lambda_{\mathrm{bnd}}\!\geq\! 0$; monoid terms encode strict inequalities; and
\begin{align*}
\varphi_{\mathrm{int}}(\cdot) &= \textstyle\sum_q \rho_q(\cdot)\big[\lambda_{\mathrm{int}}^\top A_{\mathrm{int}}(x)\big]_q + \sum_\ell \rho_\ell^\phi(\cdot)\phi_\ell(x) \\
& \quad + \rho^s(\cdot)\big(-\lambda_{\mathrm{int}}^\top r_{\mathrm{int}}(x)-s_{\mathrm{int}}^2\big),\\
\varphi_{\mathrm{bnd}}(\cdot) &= \textstyle\sum_q \rho_q(\cdot)\big[\lambda_{\mathrm{bnd}}^\top A_{\mathrm{bnd}}(x)\big]_q + \sum_\ell \rho_\ell^\phi(\cdot)\phi_\ell(x) \\
& \quad + \rho^b(\cdot)b(x) + \rho^s(\cdot)\big(-\lambda_{\mathrm{bnd}}^\top r_{\mathrm{bnd}}(x)-s_{\mathrm{bnd}}^2\big).
\end{align*}
